"""Assemble engine/mozconfig from configs/."""

from __future__ import annotations

from pathlib import Path

from .context import Context
from .util import AmayaError, info

HEADER = """\
# GENERATED by `tools/amaya import` -- do not edit.
# Edit configs/mozconfig.common, configs/mozconfig.privacy or
# configs/{platform}/mozconfig in the Amaya repository instead.
"""


def mozconfig_parts(ctx: Context) -> list[Path]:
    common = ctx.configs_dir / "mozconfig.common"
    privacy = ctx.configs_dir / "mozconfig.privacy"
    plat = ctx.configs_dir / ctx.platform / "mozconfig"
    for required in (common, plat):
        if not required.is_file():
            raise AmayaError(f"missing {required}")
    parts = [common]
    if privacy.is_file():
        parts.append(privacy)
    else:
        info("configs/mozconfig.privacy not present; skipping it")
    parts.append(plat)
    return parts


def render_mozconfig(ctx: Context) -> str:
    out = [HEADER.format(platform=ctx.platform)]
    for part in mozconfig_parts(ctx):
        rel = part.relative_to(ctx.repo)
        body = part.read_text()
        if not body.endswith("\n"):
            body += "\n"
        out.append(f"\n# ---- {rel} ----\n{body}")
    out.append(
        "\n# ---- generated by tools/amaya ----\n"
        "# Object directory lives outside the engine tree so `import` never\n"
        "# touches it.\n"
        f"mk_add_options MOZ_OBJDIR={ctx.objdir}\n"
    )
    return "".join(out)


def ensure_git_excluded(engine: Path, pattern: str) -> None:
    exclude = engine / ".git" / "info" / "exclude"
    exclude.parent.mkdir(parents=True, exist_ok=True)
    lines = exclude.read_text().splitlines() if exclude.exists() else []
    if pattern not in lines:
        lines.append(pattern)
        exclude.write_text("\n".join(lines) + "\n")


def write_mozconfig(ctx: Context) -> Path:
    path = ctx.mozconfig_path
    path.write_text(render_mozconfig(ctx))
    if (ctx.engine / ".git").is_dir():
        ensure_git_excluded(ctx.engine, "/mozconfig")
    info(f"wrote {path} (objdir {ctx.objdir})")
    return path
